package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.PortVO;

class PortValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of port of smtp outbound config")
  void test_port_value_holder_assign_plain_value() {
    Object holder = new Object();
    PortValueHolder<Object> value = new PortValueHolder<>(holder);
    Assertions.assertSame(holder, value.port(1), "Setters must return the holder");
    Assertions.assertTrue(value.getPortValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getPort().orElse(null), "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of port of smtp outbound config")
  void test_port_value_holder_assign_value_object() {
    Object holder = new Object();
    PortValueHolder<Object> value = new PortValueHolder<>(holder);
    PortVO vo = PortVO.from(1);
    Assertions.assertFalse(value.getPortValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.port(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPortValue().orElseThrow());
    Assertions.assertSame(holder, value.port(Optional.empty()));
    Assertions.assertFalse(value.getPortValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.port(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPortValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of port of smtp outbound config against the original")
  void test_port_value_holder_read() {
    Object holder = new Object();
    PortValueHolder<Object> value = new PortValueHolder<>(holder);
    PortVO vo = PortVO.from(1);
    PortVO other = PortVO.from(1);
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getPortValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPort(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readPort(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.port(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPort(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPort(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of port of smtp outbound config")
  void test_port_value_holder_unset() {
    Object holder = new Object();
    PortValueHolder<Object> value = new PortValueHolder<>(holder);
    PortVO vo = PortVO.from(1);
    value.port(vo);
    Assertions.assertSame(holder, value.unsetPortIfMatches("port_other"));
    Assertions.assertTrue(value.getPortValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPortIfMatches("port"));
    Assertions.assertFalse(value.getPortValue().isPresent(), "The field name must clear the value");
    value.port(vo);
    Assertions.assertSame(holder, value.unsetPort());
    Assertions.assertFalse(value.getPortValue().isPresent(), "Unset must clear the value");
  }
}
